.pos-chip{display:inline-flex;align-items:center;line-height:1;font-size:0.66em;font-weight:600;letter-spacing:0.02em;text-transform:var(--pos-chip-transform,none);padding:var(--pos-chip-pad,5px 11px);margin-left:2px;border-radius:var(--chip-radius,999px);background:var(--pos-chip-bg,var(--surface3));color:var(--pos-chip-fg,var(--text2));border:var(--pos-chip-border,1px solid var(--surface4));}
.pos-chip.pos-dominant{background:var(--chip-bg,var(--text1));color:var(--chip-fg,var(--surface2));border:var(--chip-border,1px solid transparent);border-bottom:var(--pos-dominant-underline,0 solid transparent);}
.meta-badge{display:inline-flex;align-items:center;line-height:1;font-size:0.66em;font-weight:600;letter-spacing:0.02em;padding:5px 11px;margin:0;border-radius:var(--chip-radius,999px);border:1px solid transparent;}
.meta-badge:empty{display:none;border:0;padding:0;margin:0;}
.meta-hsk{background:var(--hsk-bg,rgba(33,150,243,0.14));color:var(--hsk-fg,#1976d2);border-color:var(--hsk-border,rgba(33,150,243,0.35));}
.meta-freq{background:var(--freq-bg,rgba(255,152,0,0.16));color:var(--freq-fg,#e07b00);border-color:var(--freq-border,rgba(255,152,0,0.38));}
.night_mode .meta-hsk{color:var(--hsk-fg,#7ec1ff);}
.night_mode .meta-freq{color:var(--freq-fg,#ffc266);}
.info-card{margin:8px auto;width:var(--card-w);max-width:var(--card-w);box-sizing:border-box;border:var(--panel-border,1.5px solid var(--surface4));border-top:var(--panel-divider,var(--panel-border,1.5px solid var(--surface4)));background:var(--panel-bg,transparent);border-radius:var(--container-radius,16px);overflow:hidden;}
.info-card:empty{display:none;border:0;}
.info-card-title{padding:8px 12px;font-size:var(--section-title-size,0.8em);font-weight:var(--section-title-weight,700);text-transform:var(--section-title-transform,none);letter-spacing:var(--section-title-spacing,normal);color:var(--section-title-color,var(--accent));background:var(--panel-title-bg,var(--surface3));border-bottom:var(--section-title-border,none);text-align:left;}
.breakdown-row{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;padding:12px;}
.bd-item{display:flex;flex-direction:column;align-items:center;gap:3px;padding:8px 12px;min-width:56px;background:var(--tile-bg,var(--surface3));border:var(--tile-border,1px solid var(--surface4));border-radius:var(--container-radius,10px);}
.bd-char{font-size:1.5em;line-height:1;font-weight:600;}
.bd-py{font-size:0.7em;color:var(--text2);}
.bd-def{font-size:0.66em;color:var(--text2);text-align:center;line-height:1.2;}
.radical-row{display:flex;flex-wrap:wrap;gap:6px;justify-content:center;padding:12px;}
.radical-chip{display:inline-flex;align-items:center;gap:6px;font-size:0.72em;padding:4px 10px;border-radius:var(--radical-chip-radius,999px);background:var(--radical-chip-bg,var(--surface3));border:var(--radical-chip-border,1px solid var(--surface4));color:var(--text2);}
.radical-chip .radical-char{font-weight:700;color:var(--text1);}
.radical-chip .radical-rad{padding-left:6px;border-left:1px solid var(--surface4);font-size:1.05em;color:var(--radical-rad-color,inherit);}
.examples-row{margin:6px auto;width:var(--card-w);max-width:var(--card-w);box-sizing:border-box;text-align:left;display:flex;flex-direction:column;gap:12px;}
.examples-row:empty{display:none;}
.example-item{position:relative;font-size:0.85em;line-height:1.5;padding:var(--example-item-pad,10px 14px);padding-right:40px;background:var(--example-item-bg,transparent);border:var(--example-item-border,none);border-left:var(--example-item-left,var(--example-item-border,none));border-radius:var(--container-radius,16px);}
.example-tts-btn{position:absolute;top:8px;right:8px;width:26px;height:26px;padding:0;display:flex;align-items:center;justify-content:center;border:none;border-radius:50%;background:var(--surface3);color:var(--text2);cursor:pointer;}
.example-tts-btn i{font-size:16px;}
.example-tts-btn:active{background:var(--surface4);}
.example-trad,.example-sim{font-size:1em;}
.example-pinyin{font-size:0.85em;color:var(--text2);margin-top:2px;}
.example-translation{font-size:0.85em;color:var(--text2);margin-top:1px;}
.no-ex-hanzi-color .example-sim .ex-tone1,.no-ex-hanzi-color .example-sim .ex-tone2,.no-ex-hanzi-color .example-sim .ex-tone3,.no-ex-hanzi-color .example-sim .ex-tone4,.no-ex-hanzi-color .example-sim .ex-tone5,.no-ex-hanzi-color .example-trad .ex-tone1,.no-ex-hanzi-color .example-trad .ex-tone2,.no-ex-hanzi-color .example-trad .ex-tone3,.no-ex-hanzi-color .example-trad .ex-tone4,.no-ex-hanzi-color .example-trad .ex-tone5{color:inherit !important;}
.no-ex-pinyin-color .example-pinyin .ex-tone1,.no-ex-pinyin-color .example-pinyin .ex-tone2,.no-ex-pinyin-color .example-pinyin .ex-tone3,.no-ex-pinyin-color .example-pinyin .ex-tone4,.no-ex-pinyin-color .example-pinyin .ex-tone5{color:inherit !important;}
:root{--tone-1:#f44336;--tone-2:#fbc02d;--tone-3:#4caf50;--tone-4:#03a9f4;--tone-5:#858585;}
.tone1{color:#f44336;}.tone2{color:#fbc02d;}.tone3{color:#4caf50;}.tone4{color:#03a9f4;}.tone5{color:#858585;}
.ex-tone1{color:#f44336;}.ex-tone2{color:#fbc02d;}.ex-tone3{color:#4caf50;}.ex-tone4{color:#03a9f4;}.ex-tone5{color:#858585;}
